create table if not exists public.ils_professional_security_approval_execution_bindings (id uuid primary key default gen_random_uuid(),queue_id uuid not null,approval_log_id uuid not null,approved_action text not null,execution_status text not null default 'PENDING' check(execution_status in ('PENDING','READY','EXECUTED','BLOCKED','CANCELLED')),bound_at timestamptz not null default now(),executed_at timestamptz, unique(queue_id), unique(approval_log_id)); alter table public.ils_professional_security_approval_execution_bindings enable row level security; alter table public.ils_professional_security_approval_execution_bindings force row level security; revoke all on public.ils_professional_security_approval_execution_bindings from anon,authenticated; create table if not exists public.ils_professional_security_approval_execution_binding_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_security_approval_execution_binding_tests enable row level security; alter table public.ils_professional_security_approval_execution_binding_tests force row level security; revoke all on public.ils_professional_security_approval_execution_binding_tests from anon,authenticated; insert into public.ils_professional_security_approval_execution_binding_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('UNAPPROVED_QUEUE','BLOCK','BLOCK',true,'Execution requires an approved queue decision.'),('REJECTED_QUEUE','BLOCK','BLOCK',true,'Rejected security review cannot authorize execution.'),('CLOSED_QUEUE','BLOCK','BLOCK',true,'Closed review state cannot create an execution binding.'),('ACTION_MISMATCH','BLOCK','BLOCK',true,'Execution action must exactly equal approved action.'),('APPROVAL_MISMATCH','BLOCK','BLOCK',true,'Binding must reference the specific approval log.'),('DUPLICATE_QUEUE_BINDING','BLOCK','BLOCK',true,'Unique queue binding prevents replay binding.'),('DUPLICATE_APPROVAL_BINDING','BLOCK','BLOCK',true,'Unique approval-log binding prevents replay.'),('DESTRUCTIVE_ACTION','BLOCK','BLOCK',true,'Destructive action is never made executable by this binding layer.'),('CROSS_USER','BLOCK','BLOCK',true,'Execution does not expand reviewer or professional access.'),('CROSS_STREAM','BLOCK','BLOCK',true,'Binding is tied to the original queue/escalation context.'),('APPROVED_NONDESTRUCTIVE','READY','READY',true,'Only exact approved non-destructive action becomes executable-ready.'),('EXECUTION_REPLAY','BLOCK','BLOCK',true,'Executed binding cannot be replayed.'),('ATOMIC_AUDIT','REQUIRED','REQUIRED',true,'Binding retains queue and approval references for traceability.'),('LIVE_E2E','PENDING','PENDING',true,'No live approved security action exists in TEST; no synthetic binding created.');